CREATE INDEX IF NOT EXISTS "inventory_char_id" ON "inventory" ("char_id");

CREATE TABLE IF NOT EXISTS "ipbanlist" (
  "list" varchar(15) NOT NULL DEFAULT '',
  "btime" timestamp(0) NOT NULL,
  "rtime" timestamp(0) NOT NULL,
  "reason" varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY ("list", "btime")
);

CREATE TABLE IF NOT EXISTS "login" (
  "account_id" bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 2000000) NOT NULL,
  "userid" citext NOT NULL DEFAULT '',
  "user_pass" varchar(32) NOT NULL DEFAULT '',
  "sex" varchar(32) NOT NULL DEFAULT 'M' CHECK ("sex" IN ('M','F','S')),
  "email" varchar(39) NOT NULL DEFAULT '',
  "group_id" smallint NOT NULL DEFAULT 0,
  "state" bigint NOT NULL DEFAULT 0,
  "unban_time" bigint NOT NULL DEFAULT 0,
  "expiration_time" bigint NOT NULL DEFAULT 0,
  "logincount" integer NOT NULL DEFAULT 0,
  "lastlogin" timestamp(0),
  "last_ip" varchar(100) NOT NULL DEFAULT '',
  "birthdate" date,
  "character_slots" smallint NOT NULL DEFAULT 0,
  "pincode" varchar(4) NOT NULL DEFAULT '',
  "pincode_change" bigint NOT NULL DEFAULT 0,
  "vip_time" bigint NOT NULL DEFAULT 0,
  "old_group" smallint NOT NULL DEFAULT 0,
  "web_auth_token" varchar(17),
  "web_auth_token_enabled" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("account_id")
);
CREATE INDEX IF NOT EXISTS "login_name" ON "login" ("userid");
CREATE UNIQUE INDEX IF NOT EXISTS "login_web_auth_token_key" ON "login" ("web_auth_token");

