);

CREATE TABLE IF NOT EXISTS "pet" (
  "pet_id" bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL,
  "class" integer NOT NULL DEFAULT 0,
  "name" varchar(24) NOT NULL DEFAULT '',
  "account_id" bigint NOT NULL DEFAULT 0,
  "char_id" bigint NOT NULL DEFAULT 0,
  "level" integer NOT NULL DEFAULT 0,
  "egg_id" bigint NOT NULL DEFAULT 0,
  "equip" bigint NOT NULL DEFAULT 0,
  "intimate" integer NOT NULL DEFAULT 0,
  "hungry" integer NOT NULL DEFAULT 0,
  "rename_flag" smallint NOT NULL DEFAULT 0,
  "incubate" bigint NOT NULL DEFAULT 0,
  "autofeed" smallint NOT NULL DEFAULT 0,
